    descriptionAdvanced: {
      de: "Der Chimborazo ist ein inaktiver Schichtvulkan in der Westkordillere der ecuadorianischen Anden und mit 6.263 Metern der höchste Berg des Landes. Aufgrund der äquatorialen Ausbuchtung der Erde gilt sein Gipfel als der Punkt auf der Erdoberfläche, der am weitesten vom Erdmittelpunkt entfernt ist, womit er dem Weltraum näher ist als der Mount Everest. Der gewaltige Berg ist von massiven Gletschern bedeckt, die eine lebenswichtige Wasserquelle für die umliegenden Provinzen darstellen, obwohl sie durch den Klimawandel stark bedroht sind. Historisch wurde der Chimborazo durch die Expeditionen von Alexander von Humboldt im Jahr 1802 weltberühmt, auch wenn er den Gipfel damals nicht ganz erreichte. Erst im Jahr 1880 gelang Edward Whymper die offizielle Erstbesteigung. Der Berg ist Teil eines Wildtierreservats, das für den Schutz von Vicuñas bekannt ist, und stellt eine große Herausforderung für Bergsteiger aus aller Welt dar. Geologisch gehört der Vulkan zum pazifischen Feuergürtel, wobei sein letzter Ausbruch etwa um 550 n. Chr. stattfand.",
      hu: "A Chimborazo egy inaktív rétegvulkán az Andok nyugati kordillerájában, és 6263 méteres magasságával Ecuador legmagasabb hegycsúcsa. A Föld egyenlítői kidudorodása miatt a Chimborazo csúcsa a földfelszínnek az a pontja, amely a legtávolabb esik a Föld középpontjától, így közelebb van a világűrhöz, mint a Mount Everest. A hegyet hatalmas gleccserek borítják, amelyek kritikus vízforrást jelentenek a környező tartományok mezőgazdasága és lakossága számára. A hegy tudományos hírnevét Alexander von Humboldt 1802-es expedíciója alapozta meg, bár ő még nem érte el a legmagasabb pontot. Az első dokumentált csúcshódítás Edward Whymper nevéhez fűződik 1880-ban. A hegy ma egy természetvédelmi terület központja, ahol vadon élő vikunyák láthatók, és népszerű célpontja a tapasztalt hegymászóknak. Geológiai szempontból a vulkán a csendes-óceáni tűzgyűrű része, utolsó ismert kitörése i.sz. 550 körül történt.",
      ro: "Vârful Chimborazo este un stratovulcan inactiv situat în Cordiliera Occidentală a Andezilor, fiind cel mai înalt munte din Ecuador, cu o altitudine de 6.263 de metri deasupra nivelului mării. Datorită bombamentului ecuatorial al Pământului, vârful său reprezintă cel mai îndepărtat punct de centrul planetei, fiind astfel mai „aproape” de spațiul cosmic decât muntele Everest. Muntele este acoperit de ghețari masivi care furnizează apă potabilă esențială pentru provinciile învecinate Bolivar și Chimborazo. Istoria ascensiunilor sale a devenit celebră odată cu încercarea lui Alexander von Humboldt din 1802, deși prima atingere a vârfului a fost realizată de Edward Whymper în 1880. Vulcanul face parte dintr-o rezervație de producție a faunei, unde vizitatorii pot vedea vicune sălbatice protejate. Geologic, vulcanul a fost activ ultima dată în jurul anului 550 d.Hr., iar masivul său impunător poate fi văzut din orașul Guayaquil în zilele foarte senine.",
      en: "Chimborazo is an inactive stratovolcano in the Cordillera Occidental of the Andes and stands as Ecuador's highest peak at 6,263 meters (20,548 feet). Due to the Earth's equatorial bulge, its summit is the point on the planet's surface farthest from the Earth's center, making it closer to outer space than Mount Everest. The mountain is capped by massive glaciers that serve as a critical water source for the surrounding provinces, though they are currently receding due to global warming. Historically, Chimborazo gained worldwide fame through the scientific explorations of Alexander von Humboldt in 1802, although he did not reach the actual summit. The first documented successful ascent was achieved by Edward Whymper in 1880. Today, the volcano is the centerpiece of a fauna production reserve known for its protected vicuña population and remains a top challenge for high-altitude mountaineers. Geologically, it belongs to the Pacific Ring of Fire, with its last known eruption occurring around 550 AD.",
      es: "El Chimborazo es un estratovolcán inactivo en la Cordillera Occidental de los Andes ecuatorianos y, con 6.263 metros, es la montaña más alta del país. Debido al abultamiento ecuatorial de la Tierra, su cima se considera el punto de la superficie terrestre más alejado del centro del planeta, lo que lo sitúa más cerca del espacio exterior que el Monte Everest. La enorme montaña está cubierta por glaciares masivos que representan una fuente de agua vital para las provincias circundantes, aunque están muy amenazados por el cambio climático. Históricamente, el Chimborazo se hizo mundialmente famoso por las expediciones de Alexander von Humboldt en 1802, aunque no alcanzó la cima en aquel entonces. No fue hasta 1880 cuando Edward Whymper logró la primera ascensión oficial. La montaña forma parte de una reserva de producción faunística conocida por la protección de vicuñas y representa un gran desafío para los montañistas de todo el mundo. Geológicamente, el volcán pertenece al cinturón de fuego del Pacífico, habiéndose producido su última erupción alrededor del año 550 d.C.",
      pt: "O Chimborazo é um estratovulcão inativo na Cordilheira Ocidental dos Andes equatorianos e, com 6.263 metros, é a montanha mais alta do país. Devido à protuberância equatorial da Terra, o seu cume é considerado o ponto da superfície terrestre mais afastado do centro do planeta, o que o torna mais próximo do espaço sideral do que o Monte Everest. A montanha colossal está coberta por glaciares maciços, que constituem uma fonte de água vital para as províncias circundantes, embora estejam fortemente ameaçados pelas alterações climáticas. Historicamente, o Chimborazo tornou-se mundialmente famoso através das expedições de Alexander von Humboldt em 1802, embora ele não tenha atingido o cume na época. Foi apenas em 1880 que Edward Whymper conseguiu a primeira ascensão oficial. A montanha faz parte de uma reserva de vida selvagem, conhecida pela proteção de vicunhas, e constitui um grande desafio para alpinistas de todo o mundo. Geologicamente, o vulcão pertence ao Anel de Fogo do Pacífico, tendo a sua última erupção ocorrido por volta de 550 d.C.",
      fr: "Le Chimborazo est un stratovolcan inactif situé dans la Cordillère occidentale des Andes équatoriennes et, avec ses 6 263 mètres, il est la plus haute montagne du pays. En raison du renflement équatorial de la Terre, son sommet est considéré comme le point de la surface terrestre le plus éloigné du centre de la planète, ce qui le place plus près de l'espace que le mont Everest. Cette montagne imposante est couverte de glaciers massifs qui constituent une source d'eau vitale pour les provinces environnantes, bien qu'ils soient gravement menacés par le changement climatique. Historiquement, le Chimborazo est devenu mondialement célèbre grâce aux expéditions d'Alexander von Humboldt en 1802, même s'il n'avait pas atteint le sommet à l'époque. Ce n'est qu'en 1880 qu'Edward Whymper réussit la première ascension officielle. La montagne fait partie d'une réserve de faune sauvage réputée pour la protection des vigognes et représente un défi majeur pour les alpinistes du monde entier. Géologiquement, le volcan appartient à la ceinture de feu du Pacifique, sa dernière éruption remontant aux environs de l'an 550 apr. J.-C.",
    },
