    type: "mountain",
    parent: "EC-P",
    coords: [-77.983333, 0.025],
    name: {
      de: "Cayambe",
      hu: "Cayambe",
      ro: "Cayambe",
      en: "Cayambe"},
    descriptionAdvanced: {
      de: "Der Cayambe ist ein massiver, gletscherbedeckter Vulkan in der Zentralkordillere der ecuadorianischen Anden und mit einer Höhe von 5.790 Metern der dritthöchste Berg des Landes. Eine weltweit einzigartige geographische Besonderheit des Cayambe ist, dass der Äquator direkt über seinen südlichen Hang verläuft; dies ist der einzige Punkt auf der gesamten Erdoberfläche, an dem die Äquatorlinie ewiges Eis und Schnee kreuzt. Der Vulkan ist ein komplexer Schichtvulkan, dessen letzte größere Eruption im Jahr 1785 stattfand, weshalb er heute als potenziell aktiv eingestuft wird. Die Besteigung gilt aufgrund der ausgedehnten Gletscherspalten und häufiger Wetterumschwünge als technisch anspruchsvoller als die des Cotopaxi. Der Cayambe liegt innerhalb des ökologischen Reservats Cayambe-Coca, das eine enorme Artenvielfalt in verschiedenen Klimazonen von den Hochanden bis zum Amazonasbecken schützt. Historisch gesehen war der Berg ein wichtiges rituelles Zentrum für die präkolumbianische Cayambi-Kultur, die den Berg als göttliches Wesen verehrte.",
      hu: "A Cayambe egy masszív, gleccserekkel borított vulkán az Andok északi részén, és 5790 méteres magasságával Ecuador harmadik legmagasabb hegycsúcsa. Világviszonylatban egyedülálló tulajdonsága, hogy az Egyenlítő vonala közvetlenül a déli lejtőjén halad át; ez az egyetlen pont a Földön, ahol az Egyenlítő örök hóval és jéggel borított területet érint. A vulkán egy komplex rétegvulkán, amelynek utolsó jelentős kitörése 1785-ben volt, így ma potenciálisan aktívnak tekintik. A hegy megmászása a számos gleccserhasadék és a kiszámíthatatlan időjárás miatt technikailag nehezebbnek számít, mint a Cotopaxié. A Cayambe a Cayambe-Coca Ökológiai Rezervátum része, amely hatalmas biodiverzitást őriz az andoki magaslatoktól egészen az amazóniai esőerdők széléig. Történelmi szempontból a hegy a prekolumbián Cayambi kultúra szent helye volt, akik az élet forrásaként és istenségként tisztelték a vulkánt.",
      ro: "Vârful Cayambe este un vulcan masiv acoperit de ghețari, situat în Cordiliera Real a Ecuadorului, fiind al treilea cel mai înalt munte din țară, cu o altitudine de 5.790 de metri. O caracteristică geografică unică la nivel mondial este faptul că linia Ecuatorului traversează versantul său sudic; acesta este singurul loc de pe întreaga planetă unde Ecuatorul trece peste gheață și zăpadă permanentă. Vulcanul este un stratovulcan complex, a cărui ultimă erupție majoră a fost înregistrată în anul 1785, fiind clasificat în prezent ca potențial activ. Ascensiunea pe Cayambe este considerată mai tehnică decât cea pe Cotopaxi din cauza sistemului vast de crevase și a vânturilor puternice care mătură masivul. Muntele face parte din Rezervația Ecologică Cayambe-Coca, o arie protejată care adăpostește o biodiversitate incredibilă, de la condori andini până la specii rare de plante de páramo. Din punct de vedere istoric, vulcanul a fost un centru spiritual major pentru cultura precolumbiană Cayambi, care îi atribuia puteri divine.",
      en: "Cayambe is a massive, glacier-covered volcano in the Central Cordillera of the Ecuadorian Andes and stands as the country's third-highest peak at 5,790 meters (18,996 feet). A unique geographical distinction of Cayambe is that the Equator passes directly across its southern slope; this is the only point on Earth where the equatorial line crosses permanent snow and ice. The volcano is a complex stratovolcano whose last major eruption occurred in 1785, and it is currently classified as potentially active. Climbing Cayambe is considered more technically demanding than climbing Cotopaxi due to its extensive crevasse systems and unpredictable weather patterns. It lies within the Cayambe-Coca Ecological Reserve, a vast protected area that spans diverse ecosystems from high-altitude paramo to the edges of the Amazon basin. Historically, the mountain was a sacred site for the pre-Columbian Cayambi culture, who worshipped the volcano as a powerful deity and a source of life-giving water.",
      es: "El Cayambe es un volcán masivo cubierto de glaciares en la Cordillera Central de los Andes ecuatorianos y, con una altura de 5.790 metros, es la tercera montaña más alta del país. Una peculiaridad geográfica única en el mundo del Cayambe es que la línea ecuatorial pasa directamente por su ladera sur; este es el único punto en toda la superficie terrestre donde la línea ecuatorial cruza hielos y nieves perpetuas. El volcán es un complejo volcán en escudo cuya última erupción importante ocurrió en 1785, por lo que hoy se clasifica como potencialmente activo. La ascensión se considera técnicamente más exigente que la del Cotopaxi debido a las extensas grietas glaciares y los frecuentes cambios de clima. El Cayambe se encuentra dentro de la Reserva Ecológica Cayambe-Coca, que protege una enorme biodiversidad en diferentes zonas climáticas desde los altos Andes hasta la cuenca amazónica. Históricamente, la montaña fue un importante centro ritual para la cultura precolombina Cayambi, que veneraba la montaña como un ser divino.",
      pt: "O Cayambe é um vulcão maciço, coberto por glaciares, na Cordilheira Central dos Andes equatorianos e, com uma altitude de 5.790 metros, é a terceira montanha mais alta do país. Uma peculiaridade geográfica única no mundo do Cayambe é o fato de a linha do equador passar diretamente pela sua encosta sul; este é o único ponto em toda a superfície terrestre onde a linha do equador cruza gelo e neve perpétuos. O vulcão é um complexo vulcão estratificado cuja última grande erupção ocorreu em 1785, razão pela qual é hoje classificado como potencialmente ativo. A ascensão é considerada tecnicamente mais exigente do que a do Cotopaxi devido às extensas fendas nos glaciares e às frequentes mudanças de tempo. O Cayambe situa-se dentro da Reserva Ecológica Cayambe-Coca, que protege uma enorme biodiversidade em diferentes zonas climáticas, desde os altos Andes até à bacia amazônica. Historicamente, a montanha foi um importante centro ritual para a cultura pré-colombiana Cayambi, que venerava a montanha como um ser divino.",
      fr: "Le Cayambe est un imposant volcan couvert de glaciers situé dans la Cordillère centrale des Andes équatoriennes et, avec une altitude de 5 790 mètres, il est la troisième plus haute montagne du pays. Une particularité géographique unique au monde du Cayambe est que l'équateur passe directement sur son flanc sud ; c'est le seul point sur toute la surface de la terre où la ligne de l'équateur croise des neiges et des glaces éternelles. Le volcan est un stratovolcan complexe dont la dernière éruption majeure a eu lieu en 1785, ce qui lui vaut d'être classé aujourd'hui comme potentiellement actif. L'ascension est considérée comme plus technique que celle du Cotopaxi en raison des vastes crevasses glaciaires et des fréquents changements météorologiques. Le Cayambe se trouve dans la réserve écologique Cayambe-Coca, qui protège une immense biodiversité dans différentes zones climatiques, des hautes Andes au bassin amazonien. Historiquement, la montagne était un centre rituel important pour la culture précolombienne Cayambi, qui vénérait le mont comme une divinité.",
    },
