      hu: ["A Cayambe tengerszint feletti magassága 5790 méter.", "Az Egyenlítő 4690 méteres magasságban keresztezi a lejtőit.", "Az első sikeres megmászó Edward Whymper volt 1880-ban.", "Utolsó jelentős kitörése 1785-ben következett be.", "Ez az egyetlen hely a világon, ahol az Egyenlítőnél jég található.", "A vulkán a Cayambe-Coca Ökológiai Rezervátum szívében fekszik."],
      ro: ["Altitudinea maximă a vulcanului este de 5.790 de metri.", "Linia Ecuatorului trece prin punctul cel mai înalt la 4.690 m pe munte.", "Edward Whymper a realizat prima ascensiune în anul 1880.", "Ultima activitate eruptivă semnificativă a avut loc în 1785.", "Ghețarul său este unul dintre cei mai mari din Ecuador.", "Este situat la aproximativ 60 km nord-est de Quito."],
      en: ["Cayambe reaches a peak elevation of 5,790 meters.", "The Equator crosses the mountain at an altitude of 4,690 meters.", "The first recorded ascent was by Edward Whymper in 1880.", "The volcano's last major eruption was in 1785.", "It is the highest point on the planet through which the Equator passes.", "The mountain features an extensive glacier system covering its peak."],
      es: ["La altura de la cima del Cayambe es de 5.790 metros.", "La línea ecuatorial cruza la montaña a una altura de 4.690 metros.", "La primera ascensión fue realizada en 1880 por Edward Whymper.", "Su última erupción documentada fue en el año 1785.", "Es el único lugar coronado por nieve directamente sobre el ecuador.", "El volcán se encuentra a unos 60 kilómetros al noreste de Quito."],
