      hu: "A Yasuní Nemzeti Park a világ egyik legbiodiverzebb helye, egy hatalmas érintetlen esőerdő az ecuadori Amazonas-medencében.",
      ro: "Parcul Național Yasuní este unul dintre cele mai biodiverse locuri din lume, o zonă vastă de pădure tropicală neatinsă în bazinul amazonian ecuadorian.",
      en: "Yasuní National Park is one of the most biodiverse places on Earth, a vast area of pristine rainforest in the Ecuadorian Amazon basin.",
      es: "El Parque Nacional Yasuní es uno de los lugares más biodiversos del mundo, una vasta área de selva virgen en la cuenca amazónica ecuatoriana.",
      pt: "O Parque Nacional Yasuní é um dos locais com maior biodiversidade do mundo, uma vasta área de floresta tropical virgem na bacia amazónica equatoriana.",
