      es: ["Más de 100 endemismos", "Protege bosques nubosos", "Nombre: conífera", "Hábitat del oso de anteojos"],
      pt: ["Mais de 100 espécies endémicas", "Protege florestas de nuvem", "Nome: conífera", "Habitat do urso-de-óculos"],
      fr: ["Plus de 100 endémiques", "Protège les forêts de nuages", "Éponyme : conifère", "Habitat de l'ours à lunettes"],
