      es: ["Paraíso para observadores de aves", "Cientos de especies de orquídeas", "Alta pluviosidad", "Cerca de Quito"],
      pt: ["Paraíso para observadores de aves", "Centenas de espécies de orquídeas", "Elevada pluviosidade", "Perto de Quito"],
      fr: ["Paradis pour les ornithologues", "Des centaines d'espèces d'orchidées", "Précipitations élevées", "Proche de Quito"],
