      hu: "A Llanganates rejtélyes andoki páramói és köderdei Atahualpa elveszett inka aranyának legendájáról híresek.",
      ro: "Páramo-ul andin misterios și pădurile de nori din Llanganates sunt renumite pentru legenda aurului incaș pierdut al lui Atahualpa.",
      en: "The mysterious Andean páramos and cloud forests of the Llanganates are famous for the legend of the lost Inca gold of Atahualpa.",
      es: "Los misteriosos páramos andinos y bosques nubosos de Llanganates son famosos por la leyenda del oro inca perdido de Atahualpa.",
      pt: "Os misteriosos páramos andinos e florestas de nuvem de Llanganates são famosos pela lenda do ouro inca perdido de Atahualpa.",
      fr: "Les mystérieux paramos andins et les forêts de nuages des Llanganates sont célèbres pour la légende de l'or inca perdu d'Atahualpa.",
