      hu: "A Santiago-sziget drámai fekete lávapartjaival nyűgöz le, ahol medvefókák, oroszlánfókák és számtalan sziklarák él.",
      ro: "Insula Santiago impresionează prin coastele sale dramatice de lavă neagră, unde trăiesc foci cu blană, lei de mare și nenumărați crabi de stâncă.",
      en: "Santiago Island impresses with dramatic black lava coastlines home to fur seals, sea lions, and countless Sally Lightfoot crabs.",
      es: "La isla Santiago cautiva con sus dramáticas costas de lava negra, donde viven lobos peleteros, leones marinos e innumerables cangrejos de roca.",
