      hu: ["A sziget teljes területe körülbelül 173 négyzetkilométer.", "A Post Office-öböl híres hordóját 1793-ban helyezték el.", "A sziget legmagasabb pontja a 640 méteres Cerro Pajas.", "Floreana volt az első sziget, ahol 1832-ben kolóniát alapítottak.", "A Devil's Crown egy víz alatti, erodálódott vulkáni kráter.", "A Punta Cormorant lagúnáiban jelentős flamingóállomány él."],
      ro: ["Insula are o suprafață totală de aproximativ 173 kilometri pătrați.", "Butoiul poștal din Post Office Bay a fost instalat în anul 1793.", "Punctul maxim de altitudine este Cerro Pajas la 640 de metri.", "Floreana a fost prima insulă colonizată oficial, în anul 1832.", "Devil's Crown este un crater vulcanic erodat situat în ocean.", "Punta Cormorant adăpostește o lagună importantă de flamingo."],
      en: ["The island covers an area of approximately 173 square kilometers.", "The famous post office barrel was established in 1793.", "The island's highest point is Cerro Pajas at 640 meters.", "Floreana was the first island to be officially colonized in 1832.", "The Devil's Crown is a partially submerged and eroded volcanic crater.", "Punta Cormorant is home to a significant population of flamingos."],
      es: ["La isla tiene una superficie de unos 173 kilómetros cuadrados.", "El buzón de correos de Post Office Bay se instaló en 1793.", "El punto más alto de la isla es el Cerro Pajas, con 640 metros.", "Floreana fue la primera isla en la que se fundó una colonia en 1832.", "La Corona del Diablo es un cono volcánico erosionado y semisumergido.", "En Punta Cormorant hay una importante población de flamencos."],
      pt: ["A ilha tem uma área de cerca de 173 quilómetros quadrados.", "A caixa de correio na Post Office Bay foi instalada em 1793.", "A maior elevação da ilha é o Cerro Pajas com 640 metros.", "Floreana foi a primeira ilha onde foi fundada uma colónia em 1832.", "A Devil's Crown é um cone vulcânico erodido e semi-submerso.", "Na Punta Cormorant existe uma população importante de flamingos."],
      fr: ["L'île a une superficie d'environ 173 kilomètres carrés.", "La boîte aux lettres de Post Office Bay a été installée en 1793.", "Le point culminant de l'île est le Cerro Pajas, à 640 mètres.", "Floreana fut la première île où une colonie fut fondée en 1832.", "La Devil's Crown est un cône volcanique érodé et à moitié immergé.", "Punta Cormorant abrite une importante population de flamants roses."],
