      ro: ["Golful ocupă o suprafață de aproximativ 12.000 de kilometri pătrați.", "Râul Guayas se varsă aici după un curs estuarin de 60 km.", "Insula Puná are o suprafață totală de 919 kilometri pătrați.", "Golful adăpostește cele mai vaste păduri de mangrove din regiune.", "Portul Guayaquil gestionează 85% din exporturile non-petroliere.", "Adâncimea medie a golfului variază între 20 și 50 de metri."],
      en: ["The gulf covers an area of approximately 12,000 square kilometers.", "The Guayas River enters the gulf after a 60-kilometer estuary.", "Puná Island has a total surface area of 919 square kilometers.", "The gulf contains some of South America's largest mangrove forests.", "Guayaquil's port handles 85% of the country's non-oil exports.", "The average depth of the gulf ranges between 20 and 50 meters."],
      es: ["El golfo abarca una superficie de unos 12.000 km².", "El río Guayas desemboca aquí tras un recorrido de 60 km.", "La isla Puná tiene una superficie total de 919 kilómetros cuadrados.", "En el golfo se encuentran los manglares más septentrionales de Sudamérica.", "El puerto de Guayaquil maneja el 85% de las exportaciones no petroleras.", "La profundidad media del golfo oscila entre 20 y 50 metros."],
      pt: ["O golfo estende-se por uma área de cerca de 12.000 km².", "O rio Guayas desagua aqui após um percurso de 60 km.", "A ilha de Puná tem uma área total de 919 quilómetros quadrados.", "No golfo encontram-se os mangais mais setentrionais da América do Sul.", "O porto de Guayaquil processa 85% das exportações não petrolíferas.", "A profundidade média do golfo situa-se entre 20 e 50 metros."],
      fr: ["Le golfe s'étend sur une superficie d'environ 12 000 km².", "Le fleuve Guayas s'y jette après un parcours de 60 km.", "L'île de Puná a une superficie totale de 919 kilomètres carrés.", "Le golfe abrite les forêts de mangroves les plus septentrionales d'Amérique du Sud.", "Le port de Guayaquil traite 85 % des exportations non pétrolières.", "La profondeur moyenne du golfe est comprise entre 20 et 50 mètres."],
